<?php require_once __DIR__.'/_header.php'; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$d=strtolower(trim($_POST['domain']));$d=preg_replace('#^https?://#','',$d);$d=explode('/',$d)[0];if($d)db()->prepare('INSERT IGNORE INTO allowed_domains(domain) VALUES(?)')->execute([$d]);}if(isset($_GET['delete'])){db()->prepare('DELETE FROM allowed_domains WHERE id=?')->execute([(int)$_GET['delete']]);} $rows=db()->query('SELECT * FROM allowed_domains ORDER BY domain')->fetchAll();?><h1>Allowed Domains</h1><form method="post" class="card"><?=csrf_field()?><input name="domain" placeholder="example.com" required><button>Add Domain</button></form><table><tr><th>Domain</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['domain'])?></td><td><a href="?delete=<?=$r['id']?>" onclick="return confirm('Delete?')">Delete</a></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php';